// Sculpted Articulated Desert Nomad Sprinter & Spinning Brass Sawblade Trap exported from Blender 5.2 LTS.
// Nomad: 3352 verts, 6608 tris (6 parts: desert tunic+cobalt mantle, turban+head, L/R legs, L/R arms)
// Saw:   648 verts, 1248 tris (2 parts: sandstone mount+ruby gem, 8-tooth spinning brass/crimson sawblade)

const NOMAD_V = "";
const NOMAD_I = "";
const SAW_V = "";
const SAW_I = "";

function b64ToBytes(b64) {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

function decodePack(vB64, iB64) {
  const raw = new Int16Array(b64ToBytes(vB64).buffer);
  const idx = new Uint16Array(b64ToBytes(iB64).buffer);
  const count = raw.length / 10;
  const pos = new Float32Array(count * 3);
  const norm = new Float32Array(count * 3);
  const col = new Float32Array(count * 3);
  const part = new Uint8Array(count);
  const rough = new Float32Array(count);
  for (let i = 0; i < count; i++) {
    const k = i * 10;
    pos[i * 3 + 0] = raw[k + 0] * 0.001;
    pos[i * 3 + 1] = raw[k + 1] * 0.001;
    pos[i * 3 + 2] = raw[k + 2] * 0.001;
    norm[i * 3 + 0] = raw[k + 3] * 0.001;
    norm[i * 3 + 1] = raw[k + 4] * 0.001;
    norm[i * 3 + 2] = raw[k + 5] * 0.001;
    col[i * 3 + 0] = raw[k + 6] * 0.001;
    col[i * 3 + 1] = raw[k + 7] * 0.001;
    col[i * 3 + 2] = raw[k + 8] * 0.001;
    const meta = raw[k + 9];
    part[i] = Math.floor(meta / 100);
    rough[i] = (meta % 100) * 0.01;
  }
  return { count, pos, norm, col, part, rough, idx };
}

let cache = null;
export function getDesertMeshes() {
  if (cache) return cache;
  cache = {
    nomad: decodePack(NOMAD_V, NOMAD_I),
    saw: decodePack(SAW_V, SAW_I),
  };
  return cache;
}
